cd /app && python3 << 'PYEOF'
import pandas as pd
import numpy as np

df = pd.read_csv('benchmark/data.csv')

# Generate chart data as JSON for embedding
import json

# Chart 1: AI Risk Score Trend by Job Title
risk_trend = df.groupby(['year', 'job_title'])['ai_risk_score'].mean().unstack(level=1).round(3)
risk_trend_dict = {col: risk_trend[col].tolist() for col in risk_trend.columns}
risk_trend_dict['years'] = risk_trend.index.tolist()

# Chart 2: Job Survival Rate Over Time
survival = df.groupby('year').apply(lambda x: pd.Series({
    'at_risk': (x['job_survival_class'] == 0).mean() * 100,
    'moderate': (x['job_survival_class'] == 1).mean() * 100,
    'strong': (x['job_survival_class'] == 2).mean() * 100,
    'survival_rate': (x['job_survival_class'] >= 1).mean() * 100
}), include_groups=False).round(1)

# Chart 3: Median Salary Trend by Country
salary_country = df.groupby(['year', 'country'])['salary'].median().unstack(level=1).round(0)

# Chart 4: Median Salary by Job Title
salary_job = df.groupby('job_title')['salary'].median().sort_values(ascending=True)

# Chart 5: AI Risk by Job Title (bar chart)
risk_job = df.groupby('job_title')['ai_risk_score'].mean().sort_values(ascending=True)

# Chart 6: Salary vs AI Risk scatter data
salary_risk = df.groupby('ai_risk_category')['salary'].median().to_dict()

# Chart 7: Job Survival by Job Title
survival_job = df.groupby('job_title').apply(lambda x: pd.Series({
    'at_risk': (x['job_survival_class'] == 0).mean() * 100,
    'moderate': (x['job_survival_class'] == 1).mean() * 100,
    'strong': (x['job_survival_class'] == 2).mean() * 100,
}), include_groups=False).round(1)

# Chart 8: Total Job Openings by Year
openings_year = df.groupby('year')['job_openings'].sum()

# Chart 9: Skill Demand Trend
skill_demand = df.groupby(['year', 'primary_skill'])['skill_demand_score'].mean().unstack(level=1).round(1)

# Chart 10: Job Survival by Experience Level
survival_exp = df.groupby('experience_level').apply(lambda x: pd.Series({
    'at_risk': (x['job_survival_class'] == 0).mean() * 100,
    'moderate': (x['job_survival_class'] == 1).mean() * 100,
    'strong': (x['job_survival_class'] == 2).mean() * 100,
}), include_groups=False).round(1)

# Chart 11: Salary by Education Level
salary_edu = df.groupby('education_level')['salary'].median().round(0)

# Chart 12: AI Risk by Experience Level
risk_exp = df.groupby('experience_level')['ai_risk_score'].mean().round(3)

# Chart 13: High Risk Distribution by Job Title
high_risk_dist = df[df['ai_risk_category'] == 'High Risk'].groupby('job_title').size()

# Chart 14: Job Openings by Job Title (2015 vs 2035)
jo_2015 = df[df['year']==2015].groupby('job_title')['job_openings'].sum()
jo_2035 = df[df['year']==2035].groupby('job_title')['job_openings'].sum()

# Chart 15: Salary bucket vs AI risk category
crosstab = pd.crosstab(df['salary_bucket'], df['ai_risk_category'], normalize='index') * 100

# Save all chart data
chart_data = {
    'risk_trend': risk_trend_dict,
    'survival_time': {
        'years': survival.index.tolist(),
        'at_risk': survival['at_risk'].tolist(),
        'moderate': survival['moderate'].tolist(),
        'strong': survival['strong'].tolist(),
        'survival_rate': survival['survival_rate'].tolist()
    },
    'salary_country': {
        'years': salary_country.index.tolist(),
        **{col: salary_country[col].tolist() for col in salary_country.columns}
    },
    'salary_job': {
        'labels': salary_job.index.tolist(),
        'values': salary_job.values.tolist()
    },
    'risk_job': {
        'labels': risk_job.index.tolist(),
        'values': risk_job.values.tolist()
    },
    'salary_risk': salary_risk,
    'survival_job': {
        'labels': survival_job.index.tolist(),
        'at_risk': survival_job['at_risk'].tolist(),
        'moderate': survival_job['moderate'].tolist(),
        'strong': survival_job['strong'].tolist()
    },
    'openings_year': {
        'years': openings_year.index.tolist(),
        'values': openings_year.values.tolist()
    },
    'skill_demand': {
        'years': skill_demand.index.tolist(),
        **{col: skill_demand[col].tolist() for col in skill_demand.columns}
    },
    'survival_exp': {
        'labels': survival_exp.index.tolist(),
        'at_risk': survival_exp['at_risk'].tolist(),
        'moderate': survival_exp['moderate'].tolist(),
        'strong': survival_exp['strong'].tolist()
    },
    'salary_edu': {
        'labels': salary_edu.index.tolist(),
        'values': salary_edu.values.tolist()
    },
    'risk_exp': {
        'labels': risk_exp.index.tolist(),
        'values': risk_exp.values.tolist()
    },
    'high_risk_dist': {
        'labels': high_risk_dist.index.tolist(),
        'values': high_risk_dist.values.tolist()
    },
    'jo_compare': {
        'labels': jo_2015.index.tolist(),
        'y2015': jo_2015.values.tolist(),
        'y2035': jo_2035.values.tolist()
    },
    'crosstab': {
        'labels': crosstab.index.tolist(),
        'high_risk': crosstab['High Risk'].tolist(),
        'low_risk': crosstab['Low Risk'].tolist(),
        'medium_risk': crosstab['Medium Risk'].tolist()
    }
}

with open('output/chart_data.json', 'w') as f:
    json.dump(chart_data, f)

print("Chart data saved successfully")
PYEOF

